  "explanation": "HNPCC (sindromul Lynch) reprezintă 5% dintre cancerele de colon, cu predilecție pentru colonul drept la 30–40 de ani — Corect: Proporția de 5%, localizarea dreaptă și vârsta 30–40 de ani sunt explicite.\n\nTumorile sincrone se dezvoltă la 5% dintre pacienți, iar cele metacrone la 3–5% — Corect: Ratele 5% sincrone și 3–5% metacrone sunt citate.\n\nIncidența maximă este la 70 de ani, iar 90% dintre cancerele colorectale se dezvoltă după 50 de ani — Corect: Vârful la 70 de ani și 90% după 50 de ani sunt menționate.\n\nPersoanele cu risc mediu încep screeningul la 30 de ani, cu colonoscopie anuală — Incorect: Risc mediu: screening de la 50 de ani; colonoscopia la fiecare 10 ani, nu anual de la 30.\n\nSindromul PAF este responsabil de 10% din cancerele colorectale — Incorect: PAF este responsabil de 1% din cancerele colorectale, nu de 10%.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 15, p. 232, 231, Cancerul colorectal — Screening și epidemiologie (pagini PDF: 145, 144).",
