  "explanation": "Pentru fistulele colovezicale: sutură primară a vezicii și rezecție sigmoidiană cu anastomoză — Corect: Sutura vezicală plus rezecție-anastomoză este explicită.\n\nPentru fistulele colovaginale: desființarea fistulei cu rezecție sigmoidiană și anastomoză; orificiul vaginal se închide per secundam — Corect: Desființarea, rezecția și vindecarea vaginală per secundam sunt citate.\n\nMajoritatea acestor fistule se operează în urgență, manifestările fiind grav septicemice — Incorect: Majoritatea se operează elective, manifestările fiind rareori grave.\n\nHartmann este regula în fistula colovezicală electivă, anastomoza fiind evitată — Incorect: Hartmann ține de perforația liberă/obstrucție, nu de fistula electivă.\n\nOrificiul vaginal se suturează în trei straturi, vindecarea per secundam fiind contraindicată — Incorect: Textul lasă orificiul vaginal să se închidă per secundam.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 15, p. 224, Fistule diverticulare — Tehnică chirurgicală (pagini PDF: 139).",
