  "explanation": "Manevra este eficientă pentru 60–95% dintre pacienți — Corect: Intervalul 60–95% este explicit.\n\nUn tub de decompresie se lasă, în general, 1–3 zile, pentru a menține detorsionarea și a permite pregătirea mecanică — Corect: Durata 1–3 zile a tubului este citată.\n\nRezecția sigmoidului cu anastomoză, în internarea inițială, este cea mai eficientă împotriva recurenței — Corect: Rezecția-anastomoză în internarea inițială este descrisă ca cea mai eficientă anti-recidivă.\n\nDetorsionarea endoscopică a cecului este gestul de elecție, rezecția cecală fiind evitată — Incorect: Încercările de detorsionare endoscopică a cecului nu sunt, în general, recomandate.\n\nTubul de decompresie se lasă 3 săptămâni, recurența fiind rară fără rezecție — Incorect: Recurența este înaltă fără chirurgie; 3 săptămâni nu este durata tubului.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 15, p. 230, Volvulus sigmoidian — După detorsionare (pagini PDF: 143).",
