  "explanation": "30% dintre cancerele de colon sunt diseminate în ganglionii limfatici mezenterici regionali la diagnostic, de aceea mezenterul se îndepărtează odată cu segmentul — Corect: Cifra de 30% și îndepărtarea mezenterului sunt explicite.\n\nDupă rezecția anterioară joasă, marginea distală de siguranță este de 1 cm, iar anastomoza este de obicei protejată prin stomă proximală temporară — Corect: Marginea de 1 cm și stoma temporară de protecție sunt citate.\n\nExcizia incompletă a mezorectului este de principiu, grăsimea perirectală neconținând ganglioni — Incorect: Excizia completă de mezorect (grăsimea cu ganglioni) este parte importantă a tehnicii.\n\nStoma temporară după rezecția joasă crește recurența locală și se evită — Incorect: Stoma protejează de fistula anastomotică, nu crește recurența.\n\nTumorile care invadează sfincterul se tratează prin anastomoză primară, fără colostomie definitivă — Incorect: Invazia sfincterului indică rezecție abdomino-perineală și colostomie sigmoidiană definitivă.\n\nReferință: Lawrence, Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025, cap. 15, p. 234, Tratamentul chirurgical — Limfadenectomie și LAR (pagini PDF: 147).",
